mapper.select:
SELECT UM.*
FROM shopwizard.tOrdOrderUpriceMatch UM

    AND UM.ChnlName = #{pChnlName}
    AND UM.EventName = #{pEventName}
    AND UM.ProdName LIKE CONCAT('%',#{pProdName},'%')

        AND EXISTS (
            SELECT UOM.OrderNo
            FROM shopwizard.tOrdOrderUpriceOptionMatch UOM, shopwizard.tOrdOrderUprice U
            WHERE UM.OrderNo = UOM.OrderNo
            AND UOM.MatchUpriceCode = U.MatchUpriceCode
            AND U.ShopCode = #{pShopCode}
        )


         AND (UM.RegistDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND UM.RegistDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY)) 


LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*)
FROM shopwizard.tOrdOrderUpriceMatch UM

    AND UM.ChnlName = #{pChnlName}
    AND UM.EventName = #{pEventName}
    AND UM.ProdName LIKE CONCAT('%',#{pProdName},'%')

        AND EXISTS (
            SELECT UOM.OrderNo
            FROM shopwizard.tOrdOrderUpriceOptionMatch UOM, shopwizard.tOrdOrderUprice U
            WHERE UM.OrderNo = UOM.OrderNo
            AND UOM.MatchUpriceCode = U.MatchUpriceCode
            AND U.ShopCode = #{pShopCode}
        )


         AND (UM.RegistDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND UM.RegistDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY))
